    String fileName = "/tmp/ctest1-" + System.currentTimeMillis();
    String[] scripts = new String[] { "java.lang.System.out.println(\"test\");", "java.lang.Runtime.getRuntime().exec(\"bash\");", "var newBindings=loadWithNewGlobal({'script':'this','name':'ctest'});this.context.setBindings(newBindings,100);var newEngine = this.__noSuchProperty__('engine');var e=newEngine.getFactory().getScriptEngine('-Dnashorn.args=--no-java=False');e.eval('java.lang.Runtime.getRuntime().exec(\"touch /tmp/ctest1\")')", "engine.eval('malicious code')", "var str = new java.lang.String('test'); str.length()", "var file = new java.io.File('" + fileName + "'); file.createNewFile()" };
    for (String script : scripts) {
        Assert.assertNull("test: " + script, evaluator.evaluateScript(script));
    }
    File testFile = new File(fileName);
    Assert.assertFalse(fileName + ": file should not have been created", testFile.exists());
}

