@Test
public void test() {
    /*
         *  create a graph as follows:
         *           GG
         *            \
         *             v
         *   AA -> BB -> CC
         *         ^     |
         *         |     v
         *         EE <- DD -> FF
         *         |
         *         v
         *         HH
         *
         * This directed graph has
         * - 1 cycle [BB CC DD EE],
         * - 2 sources [AA GG],
         * - 2 sinks [HH FF]
         * - 4 hierarchies { [AA BB CC DD FF], [AA BB CC DD EE HH], [GG CC DD FF], [GG CC DD EE HH] }
         */
    DirectedGraph graph = new DirectedGraph();
    // first add all of the arcs - from top row to bottom row and from left to right
    //1st row
    graph.addArc("GG", "CC");
    // 2nd row
    graph.addArc("AA", "BB");
    graph.addArc("BB", "CC");
    // 3rd row
    graph.addArc("EE", "BB");
    graph.addArc("DD", "EE");
    graph.addArc("CC", "DD");
    graph.addArc("DD", "FF");
    // 4th row
    graph.addArc("EE", "HH");
    // now assert the structure
    assertEquals(Sets.newHashSet("FF", "HH"), graph.getSinks());
    assertEquals(Sets.newHashSet("AA", "GG"), graph.getSources());
    // check paths
    assertEquals(Lists.newArrayList("AA", "BB", "CC", "DD", "FF"), graph.getAPath("AA", "FF", new HashSet<>()));
    // BB is not reachable from GG
    assertEquals(Lists.newArrayList(), graph.getAPath("GG", "AA", new HashSet<>()));
    assertEquals(Lists.newArrayList("GG", "CC", "DD", "EE", "BB"), graph.getAPath("GG", "BB", new HashSet<>()));
    assertEquals(Lists.newArrayList("GG", "CC", "DD", "FF"), graph.getAPath("GG", "FF", new HashSet<>()));
    assertEquals(Lists.newArrayList("EE", "BB", "CC", "DD", "FF"), graph.getAPath("EE", "FF", new HashSet<>()));
}

