@Test
public final void test_isValidResourceGraph() {
    Object[][] dataBad = new Object[][] { //  { name,  excludesSupported, recursiveSupported, mandatory, reg-exp, parent-level, level }
    { "db", null, null, null, null, "", 10 }, // same as db's level
    { "table", null, null, null, null, "db", 20 }, // level is null!
    { "column-family", null, null, null, null, "table", null }, // level is duplicate for [db->table->column-family-> column] hierarchy
    { "column", null, null, null, null, "column-family", 20 }, // udf's id conflicts with that of db in the [db->udf] hierarchy
    { "udf", null, null, null, null, "db", 10 } };
    List<RangerResourceDef> resourceDefs = utils.createResourceDefs(dataBad);
    when(serviceDef.getResources()).thenReturn(resourceDefs);
    when(serviceDef.getName()).thenReturn("service-name");
    when(serviceDef.getUpdateTime()).thenReturn(new Date());
    failures.clear();
    assertFalse(validator.isValidResourceGraph(serviceDef, failures));
    utils.checkFailureForMissingValue(failures, "resource level");
    // level 20 is duplicate for 1 hierarchy
    utils.checkFailureForSemanticError(failures, "resource level", "20");
    // level 10 is duplicate for another hierarchy
    utils.checkFailureForSemanticError(failures, "resource level", "10");
    dataBad = new Object[][] { //  { name,  excludesSupported, recursiveSupported, mandatory, reg-exp, parent-level, level }
    { "db", null, null, null, null, "", 10 }, { "table", null, null, null, null, "db", 20 }, // level is smaller than table!
    { "column-family", null, null, null, null, "table", 15 }, { "column", null, null, null, null, "column-family", 30 }, { "udf", null, null, null, null, "db", 15 } };
    resourceDefs = utils.createResourceDefs(dataBad);
    when(serviceDef.getResources()).thenReturn(resourceDefs);
    when(serviceDef.getName()).thenReturn("service-name");
    when(serviceDef.getUpdateTime()).thenReturn(new Date());
    failures.clear();
    assertFalse(validator.isValidResourceGraph(serviceDef, failures));
    // level 20 is duplicate for 1 hierarchy
    utils.checkFailureForSemanticError(failures, "resource level", "15");
    Object[][] dataGood = new Object[][] { //  { name,  excludesSupported, recursiveSupported, mandatory, reg-exp, parent-level, level }
    // -ve level is ok
    { "db", null, null, null, null, "", -10 }, // 0 level is ok
    { "table", null, null, null, null, "db", 0 }, // level is null!
    { "column", null, null, null, null, "table", 10 }, // should not conflict as it belong to a different hierarchy
    { "udf", null, null, null, null, "db", 0 } };
    resourceDefs = utils.createResourceDefs(dataGood);
    when(serviceDef.getResources()).thenReturn(resourceDefs);
    failures.clear();
    assertTrue(validator.isValidResourceGraph(serviceDef, failures));
    assertTrue(failures.isEmpty());
    Object[][] dataCycles = new Object[][] { //  { name,  excludesSupported, recursiveSupported, mandatory, reg-exp, parent-level, level }
    // -ve level is ok
    { "db", null, null, null, null, "column", -10 }, // 0 level is ok
    { "table", null, null, null, null, "db", 0 }, // level is null!
    { "column", null, null, null, null, "table", 10 }, // should not conflict as it belong to a different hierarchy
    { "udf", null, null, null, null, "db", -5 } };
    resourceDefs = utils.createResourceDefs(dataCycles);
    when(serviceDef.getResources()).thenReturn(resourceDefs);
    failures.clear();
    assertFalse("Graph was valid!", validator.isValidResourceGraph(serviceDef, failures));
    assertFalse(failures.isEmpty());
    utils.checkFailureForSemanticError(failures, "resource graph");
    dataBad = new Object[][] { //  { name,  excludesSupported, recursiveSupported, mandatory, reg-exp, parent-level, level }
    // -ve level is ok
    { "db", null, null, null, null, "", -10 }, // 0 level is ok; mandatory true here, but not at parent level?
    { "table", null, null, true, null, "db", 0 }, // level is null!
    { "column", null, null, null, null, "table", 10 }, // should not conflict as it belong to a different hierarchy
    { "udf", null, null, null, null, "db", 0 } };
    resourceDefs = utils.createResourceDefs(dataBad);
    when(serviceDef.getResources()).thenReturn(resourceDefs);
    failures.clear();
    assertFalse(validator.isValidResourceGraph(serviceDef, failures));
    assertFalse(failures.isEmpty());
    dataGood = new Object[][] { //  { name,  excludesSupported, recursiveSupported, mandatory, reg-exp, parent-level, level }
    // -ve level is ok
    { "db", null, null, true, null, "", -10 }, // 0 level is ok; mandatory true here, but not at parent level?
    { "table", null, null, null, null, "db", 0 }, // level is null!
    { "column", null, null, null, null, "table", 10 }, // should not conflict as it belong to a different hierarchy
    { "udf", null, null, true, null, "db", 0 } };
    resourceDefs = utils.createResourceDefs(dataGood);
    when(serviceDef.getResources()).thenReturn(resourceDefs);
    failures.clear();
    assertTrue(validator.isValidResourceGraph(serviceDef, failures));
    assertTrue(failures.isEmpty());
}

