    Object[][] testData = { { "database", "database", 1, "database" }, { "database/table", "table", 2, "database", "table" }, { "database/table/column", "column", 3, "database", "table", "column" }, { "bucket", "bucket", 1, "bucket" }, { "bucket/path", "path", 2, "bucket", "path" }, { "storageaccount", "storageaccount", 1, "storageaccount" }, { "storageaccount/container", "container", 2, "storageaccount", "container" }, { "storageaccount/container/relativepath", "relativepath", 3, "storageaccount", "container", "relativepath" }, { "catalog", "catalog", 1, "catalog" }, { "catalog/schema", "schema", 2, "catalog", "schema" }, { "catalog/schema/table", "table", 3, "catalog", "schema", "table" }, { "catalog/schema/table/column", "column", 4, "catalog", "schema", "table", "column" }, { "catalog/schema/procedure", "procedure", 3, "catalog", "schema", "procedure" }, { "catalog/schema/schemafunction", "schemafunction", 3, "catalog", "schema", "schemafunction" }, { "catalog/sessionproperty", "sessionproperty", 2, "catalog", "sessionproperty" } };
    for (Object[] test : testData) {
        String template = (String) test[0];
        String resourceType = (String) test[1];
        int resourceCount = (Integer) test[2];
        RangerResourceNameParser resourceTemplate = new RangerResourceNameParser(template);
        assertEquals(resourceType, resourceTemplate.getResourceType(), template);
        assertEquals(resourceCount, resourceTemplate.count(), template);
        assertEquals(template, resourceTemplate.getTemplate(), template);
        for (int i = 0; i < resourceCount; i++) {
            assertEquals(test[i + 3], resourceTemplate.resourceAt(i), template + " at " + i);
        }
    }
}

