    assertEquals("db1/tbl\\/1/col1", templates.get("column").toResourceName(toArray("db1", "tbl/1", "col1")));
    assertEquals("db1/tbl\\/1/col/1", templates.get("column").toResourceName(toArray("db1", "tbl/1", "col/1")));
    // validate null or missing entries in array
    assertEquals("", templates.get("database").toResourceName((Map<String, String>) null));
    assertEquals("", templates.get("database").toResourceName(Collections.emptyMap()));
    assertEquals("/", templates.get("table").toResourceName((Map<String, String>) null));
    assertEquals("/", templates.get("table").toResourceName(Collections.emptyMap()));
    // null database name
    assertEquals("/tbl1", templates.get("table").toResourceName(toArray(null, "tbl1")));
    // missing table name
    assertEquals("db1/", templates.get("table").toResourceName(toArray("db1")));
    // null array
    assertEquals("//", templates.get("column").toResourceName((String[]) null));
    // empty array
    assertEquals("//", templates.get("column").toResourceName(new String[0]));
    // null database name
    assertEquals("/tbl1/col1", templates.get("column").toResourceName(toArray(null, "tbl1", "col1")));
    // null table name
    assertEquals("db1//col1", templates.get("column").toResourceName(toArray("db1", null, "col1")));
    // null column name
    assertEquals("db1/tbl1/", templates.get("column").toResourceName(toArray("db1", "tbl1", null)));
    // missing column name
    assertEquals("db1/tbl1/", templates.get("column").toResourceName(toArray("db1", "tbl1")));
    // validate unknown entries in map
    assertEquals("db1", templates.get("database").toResourceName(toArray("db1", "ignore")));
}

