@Test
void testDoExportMKToAzureKeyVault_WhenMasterKeyMissing_ShouldThrow() throws Exception {
    // 1. Instance of the class under test
    DBToAzureKeyVault vault = new DBToAzureKeyVault();
    // 2. Grab the private method via reflection
    Method m = DBToAzureKeyVault.class.getDeclaredMethod("doExportMKToAzureKeyVault", // sslEnabled
    boolean.class, // key name/type/algo
    String.class, // key name/type/algo
    String.class, // key name/type/algo
    String.class, // clientId + vault‑URL
    String.class, // clientId + vault‑URL
    String.class, // pwd/cert + certPwd
    String.class, // pwd/cert + certPwd
    String.class, // Hadoop conf
    Configuration.class);
    m.setAccessible(true);
    // 3. Build a Configuration that will FAIL the very first check
    Configuration conf = new Configuration();
    // triggers IOException path
    conf.set("ranger.db.encrypt.key.password", "crypted");
    // 4. Parameters – values after the first three don’t matter for this test
    Object[] params = { // sslEnabled
    false, // masterKeyName
    "testKey", // masterKeyType
    "RSA", // zoneKeyEncryptionAlgo
    "AES", // azureClientId
    "clientId", // azureKeyVaultUrl
    "https://dummy.vault", // passwordOrCertPath
    "secretOrPem", // certificatePassword
    null, // Hadoop conf
    conf };
    // ---- act / assert -------------------------------------------------------------
    InvocationTargetException ite = assertThrows(InvocationTargetException.class, () -> m.invoke(vault, params));
    // unwrap and assert message
    Throwable cause = ite.getCause();
    assertInstanceOf(RuntimeException.class, cause);
    assertTrue(cause.getMessage().contains("Unable to import Master key from Ranger DB to Azure Key Vault"));
}

