    p2.setId(2L);
    p2.setName("B");
    @SuppressWarnings("unchecked")
    Comparator<RangerPolicy> byIdDesc = (Comparator<RangerPolicy>) m.invoke(serviceREST, SearchFilter.POLICY_ID, "DESC");
